import * as T from '../vendor/three.module.js';
export function createBattleChariots({world,scene,actors,navigation,getCombat,onMessage=()=>{}}){
 const vehicles=[],parts=[];let motion={x:0,z:0},rise=0;
 for(let team=0;team<2;team++)for(let i=0;i<2;i++){const root=new T.Group(),pad=world.pads[team],home=new T.Vector3(pad.x+(i?9:-9),pad.y+1,pad.z+8),id='chariot-'+team+'-'+i,mat=new T.MeshStandardMaterial({color:team?0x493447:0xc4ae73,roughness:1});
  const hull=new T.Mesh(new T.BoxGeometry(3.8,1.2,4.8),mat);root.add(hull);hull.userData.vehicleId=id;parts.push(hull);world.solids.push(hull);
  for(const side of [-1,1]){const wheel=new T.Mesh(new T.TorusGeometry(1.2,.22,4,12),mat);wheel.position.set(side*2,-.1,0);wheel.rotation.y=Math.PI/2;root.add(wheel);const wing=new T.Mesh(new T.BoxGeometry(4,.12,2),mat);wing.position.set(side*3,.5,-.5);wing.rotation.z=side*.18;root.add(wing);}
  const flame=new T.Mesh(new T.OctahedronGeometry(.65,0),new T.MeshBasicMaterial({color:0xd5fff5}));flame.position.set(0,-1.4,0);root.add(flame);root.position.copy(home);scene.add(root);root.visible=false;vehicles.push({id,team,root,home,hp:260,maxHp:260,seats:[{actor:null}],velocity:new T.Vector3(),collisionHalfSize:new T.Vector3(4.8,2,3),collisionOffset:new T.Vector3(),respawnAt:0,flame});}
 function exit(a=actors[0]){const v=vehicles.find(v=>v.id===a.mount?.chariot);if(!v)return false;v.seats[0].actor=null;a.mount=null;Object.assign(a.state,{x:v.root.position.x+5,y:v.root.position.y+2,z:v.root.position.z,flight:true,manual:true,grounded:false,vy:0});a.path=[];a.pathIndex=0;a.decisionAt=getCombat().state.time;return true;}
 function interact(a=actors[0]){if(a.mount?.chariot)return exit(a);if(a.mount||!a.alive)return false;const v=vehicles.find(v=>v.team===a.team&&v.hp>0&&!v.seats[0].actor&&v.root.position.distanceTo(new T.Vector3(a.state.x,a.state.y,a.state.z))<14);if(!v){const nearest=vehicles.filter(v=>v.team===a.team&&v.hp>0&&!v.seats[0].actor).sort((v,w)=>v.root.position.distanceTo(new T.Vector3(a.state.x,a.state.y,a.state.z))-w.root.position.distanceTo(new T.Vector3(a.state.x,a.state.y,a.state.z)))[0],distance=nearest?Math.ceil(nearest.root.position.distanceTo(new T.Vector3(a.state.x,a.state.y,a.state.z))):null;onMessage(distance===null?'No unoccupied friendly chariot nearby.':('Friendly chariot '+distance+'m away · approach within14m and press R.'));return false;}a.planController?.abort();a.planToken++;a.planning=false;a.spawnPending=false;a.path=[];a.pathIndex=0;a.mount={chariot:v.id};v.seats[0].actor=a;a.role='Charioteer';a.reason='Fast solo flight to an objective';if(a.human)onMessage('FLYING CHARIOT · WASD steer · R/C rise/lower · F exit · personal weapons');return true;}
 function reset(){for(const v of vehicles){if(v.seats[0].actor)exit(v.seats[0].actor);v.root.position.copy(v.home);v.velocity.set(0,0,0);v.hp=v.maxHp;v.respawnAt=0;v.seats[0].actor=null;v.root.visible=false;}}
 function sync(){for(const v of vehicles){const pad=world.pads[v.team];v.home.set(pad.x+(v.id.endsWith('1')?9:-9),pad.y+1,pad.z+8);}reset();}
 function step(dt){const c=getCombat();for(const v of vehicles){v.root.visible=v.hp>0;if(v.hp<=0){if(v.seats[0].actor)exit(v.seats[0].actor);v.respawnAt||=c.state.time+20;if(c.state.phase==='running'&&c.state.time>=v.respawnAt){v.hp=v.maxHp;v.respawnAt=0;v.root.position.copy(v.home);}continue;}let a=v.seats[0].actor;if(a&&(!a.alive||a.mount?.chariot!==v.id)){exit(a);v.seats[0].actor=null;a=null;}if(!a&&c.state.phase==='running'&&actors.filter(a=>a.team===v.team).length>=4){const bot=actors.find(a=>!a.human&&a.alive&&!a.mount&&!a.fleetTask&&!a.defenseTask&&a.team===v.team&&a.ordinal%8===2&&v.root.position.distanceTo(new T.Vector3(a.state.x,a.state.y,a.state.z))<14);if(bot)interact(bot);a=v.seats[0].actor;}
   if(!a){v.velocity.multiplyScalar(Math.exp(-dt*4));continue;}let input;if(a.human)input=new T.Vector3(motion.x,rise,motion.z);else{const o=c.objectives.filter(o=>o.owner!==a.team).sort((a,b)=>v.root.position.distanceTo(new T.Vector3(a.x,a.y,a.z))-v.root.position.distanceTo(new T.Vector3(b.x,b.y,b.z)))[0]||c.objectives[0];if(!o)continue;const target=new T.Vector3(o.x,o.y+9,o.z),distance=Math.hypot(v.root.position.x-o.x,v.root.position.z-o.z);if(distance>20)target.y=150;else if(v.root.position.distanceTo(target)<4){exit(a);continue;}input=target.sub(v.root.position).normalize();}
   if(input.length()>1)input.normalize();v.velocity.lerp(input.multiplyScalar(88),1-Math.exp(-dt*5));const before=v.root.position.clone(),after=before.clone().addScaledVector(v.velocity,dt);after.y=T.MathUtils.clamp(after.y,4,220);after.x=T.MathUtils.clamp(after.x,-560,560);after.z=T.MathUtils.clamp(after.z,-560,560);const hit=c.collision.firstHit(before,after,new Set(parts));if(!hit)v.root.position.copy(after);else v.velocity.set(0,0,0);if(v.velocity.lengthSq()>1)v.root.rotation.y=Math.atan2(v.velocity.x,v.velocity.z);Object.assign(a.state,{x:v.root.position.x,y:v.root.position.y+1,z:v.root.position.z,vx:v.velocity.x,vy:v.velocity.y,vz:v.velocity.z,flight:false,grounded:false});v.flame.scale.setScalar(1+.25*Math.sin(c.state.time*30));
  }}
 return {vehicles,parts,interact,exit,step,reset,sync,setMotion(input,vertical){motion=input;rise=vertical;},status(){return actors[0].mount?.chariot?'FLYING CHARIOT · 88m/s · F exit':'R · Enter flying chariot';},snapshot:()=>vehicles.map(v=>({id:v.id,hp:v.hp,pilot:v.seats[0].actor?.id??null,x:v.root.position.x,y:v.root.position.y,z:v.root.position.z}))};
}
